insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '1249bddf-4360-507d-aaf9-7403970e3285', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '1.1' limit 1), '1.1 Perspectives · Lesson 1: Environmental perspectives, values and the history of the environmental movement', 'IB DP ESS · 1.1 Perspectives', '/ess11-lesson1/', 'ESS-11-L1', 23, 1 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-11-L1', '1.1 Perspectives · Lesson 1: Environmental perspectives, values and the history of the environmental movement', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Instrumental value", "Intrinsic value", "Instrumental value", "Intrinsic value"], "tip": "Is the value about usefulness to people?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Technocentric", "Anthropocentric", "Ecocentric", "Technocentric", "Anthropocentric"], "tip": "Nature first, managed for people, or technology fixes it?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["ecocentric+intrinsic", "ecocentric+nature", "ecocentric+less", "ecocentric+limit"], ["technocentric+technology", "technocentric+innovation", "technocentric+science"], ["growth", "consumption", "both", "lifestyle"]], "tips": ["Values, solutions, attitude to growth."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Silent Spring (1962)", "Stockholm Conference (1972)", "Green Belt Movement (1977)", "Chernobyl (1986)", "Paris Agreement (2015)"], "tip": "One each."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 4, "pts": [["technocentric", "anthropocentric"], ["energy", "electricity", "economic", "development"], ["ecocentric", "indigenous"], ["intrinsic", "forest", "flood", "culture", "loss"]], "tips": ["Two perspectives, each with a reason."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["silent spring", "chernobyl", "minamata", "bhopal", "stockholm"], ["awareness", "law", "ban", "movement", "policy"]], "tips": ["Event + effect."]}]}, "models": {"1": [["Q1", "Timber and tourism: instrumental. Right to exist and sacred mountain: intrinsic."]], "2": [["Q2", "Geoengineering and lab-grown meat: technocentric. Carbon tax and zoning/EIA: anthropocentric. Consume less: ecocentric."], ["Q3", "Ecocentrics value nature intrinsically and want to limit consumption and live within nature''s limits [1]; technocentrics believe technology and scientific innovation can solve environmental problems [1]; ecocentrics reject unlimited economic growth whereas technocentrics believe growth and consumption can continue [1]."]], "3": [["Q4", "Silent Spring; Stockholm; Green Belt Movement; Chernobyl; Paris Agreement."]], "4": [["Q5", "A technocentric or anthropocentric government would support the dam [1] because it provides renewable electricity and economic development [1]; an ecocentric view, shared by the indigenous community [1], would oppose it because the forest has intrinsic and cultural value and flooding would destroy habitat and their way of life [1]."]], "5": [["Q6", "Rachel Carson''s Silent Spring (1962) showed DDT harming birds [1], raising public awareness and leading to pesticide bans and the growth of the environmental movement [1]."]], "6": [["Exit ticket", "Any position, justified, e.g. anthropocentric: I think regulation and planning can manage resources sustainably for people."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '12338736-eb04-57da-8c13-1fce510bd1a9', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '1.2' limit 1), '1.2 Systems · Lesson 1: Systems, models, energy laws, feedback and equilibrium', 'IB DP ESS · 1.2 Systems', '/ess12-lesson1/', 'ESS-12-L1', 19, 11 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-12-L1', '1.2 Systems · Lesson 1: Systems, models, energy laws, feedback and equilibrium', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Open system", "Closed system", "Transformation", "Transfer", "Transformation"], "tip": "Does it change form?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["heat", "degraded", "entropy"], ["less energy", "decrease", "fewer trophic", "inefficient", "lost"]], "tips": ["Each transfer loses some energy as..."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Negative feedback", "Positive feedback", "Positive feedback", "Negative feedback"], "tip": "Counteracts or amplifies?"}, {"kind": "text", "id": "q3_1", "q": "Q4", "max": 3, "pts": [["amplif", "reinforc", "increase", "accelerat"], ["threshold", "tipping point"], ["new equilibrium", "new state", "irreversible", "cannot return"]], "tips": ["Amplify → threshold → new state."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["predict", "scenario", "test", "simplif"], ["oversimplif", "assumption", "data", "uncertain", "not include"], ["different models", "range", "conclusion", "useful"]], "tips": ["A strength, a limitation, a judgement."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["transfer+without", "transfer+same", "transfer+movement"], ["transformation+change", "transformation+form", "transformation+state"]], "tips": ["Same form vs change of form."]}]}, "models": {"1": [["Q1", "Delta: open. Earth: closed. Evaporation and photosynthesis: transformations. Nutrients carried downstream: transfer."]], "2": [["Q2", "At each energy transformation, such as respiration, some energy is degraded to heat [1], so less energy is available to each higher trophic level and food chains are short [1]."]], "3": [["Q3", "Predator–prey and carrying capacity: negative. Permafrost and fire–drying: positive."], ["Q4", "Positive feedback amplifies a change, so the system moves further from equilibrium [1]; if the change passes a threshold (tipping point) [1], the system shifts to a new equilibrium and may not return, e.g. rainforest becoming savanna [1]."]], "4": [["Q5", "Climate models allow scientists to predict future temperatures under different emission scenarios [1]; however they oversimplify the climate system and depend on assumptions and data quality, so predictions are uncertain [1]; different models give a range of results, so they are useful for policy but should be used with caution [1]."]], "5": [["Q6", "A transfer moves matter or energy without changing its form, e.g. water flowing in a river [1]; a transformation changes its form or state, e.g. water evaporating to vapour [1]."]], "6": [["Exit ticket", "An open system exchanges energy and matter with its surroundings; a closed system exchanges energy but not matter."]]}, "labels": {"q2_0": "Q2", "q3_1": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '73c70fe8-2273-5f72-b29d-3f946b4d7a5b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '1.3' limit 1), '1.3 Sustainability · Lesson 1: Natural capital, ecosystem services, footprints and frameworks for sustainability', 'IB DP ESS · 1.3 Sustainability', '/ess13-lesson1/', 'ESS-13-L1', 20, 21 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-13-L1', '1.3 Sustainability · Lesson 1: Natural capital, ecosystem services, footprints and frameworks for sustainability', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Natural capital", "Natural income", "Natural capital", "Natural income"], "tip": "Stock or yield?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Regulating", "Provisioning", "Cultural", "Supporting", "Regulating"], "tip": "Products, regulation, culture or underlying processes?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["consum", "more resources", "goods"], ["energy", "fossil fuel", "car", "travel"], ["meat", "diet", "waste", "imported"]], "tips": ["Think consumption, energy, food."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 5, "n": 5, "ans": ["SDGs", "Doughnut economics", "Planetary boundaries", "Circular economy", "EIA"], "tip": "One each."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["baseline", "before"], ["impact", "predict", "identify"], ["mitigat", "alternative", "decision", "reduce"]], "tips": ["Before, predict, reduce."]}]}, "models": {"1": [["Q1", "Forest and fish stock: capital. Annual growth and sustainable catch: income."]], "2": [["Q2", "Mangroves and bees: regulating. Fish: provisioning. Safari: cultural. Decomposers: supporting."]], "3": [["Q3", "People in high-income countries consume more goods and resources [1]; they use more energy, much of it from fossil fuels for heating, cars and flights [1]; diets contain more meat and imported food, and more waste is produced [1]."]], "4": [["Q4", "SDGs; doughnut; planetary boundaries; circular economy; EIA."]], "5": [["Q5", "An EIA is carried out before a development, starting with a baseline study of the environment [1]; it predicts and identifies the likely environmental impacts [1]; it proposes mitigation measures or alternatives and informs the decision on whether to approve the project [1]."]], "6": [["Exit ticket", "Natural capital is the stock of natural resources; natural income is the sustainable yield from it."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '07a5ef36-81de-53a6-9be7-d20254db81fe', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '2.1' limit 1), '2.1 Individuals, populations, communities and ecosystems · Lesson 1: Species, populations, niches, interactions and population growth', 'IB DP ESS · 2.1 Individuals, populations, communities and ecosystems', '/ess21-lesson1/', 'ESS-21-L1', 20, 31 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-21-L1', '2.1 Individuals, populations, communities and ecosystems · Lesson 1: Species, populations, niches, interactions and population growth', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Population", "Community", "Ecosystem", "Habitat", "Niche"], "tip": "One species, many species, plus environment?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Competition", "Parasitism", "Herbivory", "Mutualism", "Predation"], "tip": "Who benefits, who is harmed?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["limiting", "resources", "food", "space"], ["competition", "predation", "disease", "density"], ["carrying capacity", "births equal deaths", "birth rate = death rate"]], "tips": ["Resources, density-dependent factors, carrying capacity."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 5, "n": 5, "ans": ["K-strategist", "r-strategist", "K-strategist", "r-strategist", "r-strategist"], "tip": "Many and cheap, or few and cared for?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["density-dependent+increase", "density-dependent+competition", "density-dependent+disease", "dependent+predation"], ["independent+drought", "independent+flood", "independent+fire", "independent+regardless"]], "tips": ["Does density matter?"]}]}, "models": {"1": [["Q1", "Population; community; ecosystem; habitat; niche."]], "2": [["Q2", "Lions and hyenas: competition. Tapeworm: parasitism. Elephant: herbivory. Lichen: mutualism. Cheetah: predation."]], "3": [["Q3", "As the population grows, resources such as food and space become limiting [1]; density-dependent factors such as competition, predation and disease increase [1]; the birth rate falls and death rate rises until they are equal at the carrying capacity [1]."]], "4": [["Q4", "Elephant and gorilla: K. Mosquito, dandelion and type III: r."]], "5": [["Q5", "Density-dependent factors increase in effect as population density rises, e.g. competition or disease [1]; density-independent factors act regardless of density, e.g. drought or floods [1]."]], "6": [["Exit ticket", "The maximum population size of a species that an environment can sustainably support."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '20b45987-0f5c-5fc1-8713-1c2046ca135a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '2.1' limit 1), '2.1 Individuals, populations, communities and ecosystems · Lesson 2: Sampling and measuring populations and biodiversity', 'IB DP ESS · 2.1 Individuals, populations, communities and ecosystems', '/ess21-lesson2/', 'ESS-21-L2', 13, 32 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-21-L2', '2.1 Individuals, populations, communities and ecosystems · Lesson 2: Sampling and measuring populations and biodiversity', '{"marks": {"2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["2 per quadrat", "8 per m²", "4000", "Systematic sampling along a transect"], "tip": "2 ÷ 0.25 = 8 per m²."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 2, "n": 2, "ans": ["180", "Marked beetles mix fully with the population"], "tip": "45 × 60 ÷ 15."}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 3, "n": 3, "ans": ["600", "3.0", "Site with higher D"], "tip": "N(N−1) = 600; 600 ÷ 200."}, {"kind": "text", "id": "q4_1", "q": "Q5", "max": 2, "pts": [["evenness", "abundance", "relative", "numbers of each"], ["dominat", "same richness", "compare", "different"]], "tips": ["Two sites with the same number of species…"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["mark", "lost", "harm", "predator"], ["migration", "births", "deaths", "not mix", "trap"]], "tips": ["Marks and the population changing."]}]}, "models": {"1": [["Q1", "1a Has legs → go to 2; 1b No legs → earthworm. 2a Eight legs → spider; 2b Six legs → beetle."]], "2": [["Q2", "40 ÷ 20 = 2 per quadrat; 2 ÷ 0.25 = 8 per m²; 8 × 500 = 4000. A transect suits a gradient."]], "3": [["Q3", "45 × 60 ÷ 15 = 180 beetles; assumes full mixing (and no births, deaths or migration)."]], "4": [["Q4", "N(N−1) = 25 × 24 = 600; D = 600 ÷ 200 = 3.0. Higher D suggests less disturbance."], ["Q5", "Simpson''s index takes into account the abundance (evenness) of each species, not just the number of species [1]; two sites with the same richness can differ if one species dominates, and the index shows this difference [1]."]], "5": [["Q6", "Marks may rub off or make animals more visible to predators [1]; births, deaths or migration between samples, or incomplete mixing, make the estimate inaccurate [1]."]], "6": [["Exit ticket", "N = (n₁ × n₂) ÷ m₂."]]}, "labels": {"q1_0": "Q1", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'cdf11040-52cf-5e77-9f51-9f8db5102826', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '2.2' limit 1), '2.2 Energy and biomass in ecosystems · Lesson 1: Trophic levels, ecological pyramids, productivity and biomagnification', 'IB DP ESS · 2.2 Energy and biomass in ecosystems', '/ess22-lesson1/', 'ESS-22-L1', 14, 41 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-22-L1', '2.2 Energy and biomass in ecosystems · Lesson 1: Trophic levels, ecological pyramids, productivity and biomagnification', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Producer", "Primary consumer", "Secondary consumer", "Decomposer"], "tip": "Who eats what?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["energy", "lost", "heat", "respiration"], ["each level", "less", "second law"]], "tips": ["Energy is lost at every step."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 3, "n": 3, "ans": ["15 000", "800", "200"], "tip": "NPP = GPP − R; GSP = eaten − faeces; NSP = GSP − R."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["energy lost", "10%", "lost", "respiration"], ["lower trophic", "directly", "eat plants", "fewer levels"]], "tips": ["Trophic levels and energy loss."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["persistent", "not broken down", "fat", "not excreted"], ["accumulat", "eat many", "each level"], ["top predator", "highest", "biomagnif"]], "tips": ["Persistence, eating many, top level."]}]}, "models": {"1": [["Q1", "Phytoplankton: producer. Zooplankton: primary consumer. Sardines: secondary consumer. Bacteria: decomposer."]], "2": [["Q2", "Energy is lost at each transfer, mainly as heat from respiration [1], so each trophic level always has less energy flow than the one below it (second law of thermodynamics) [1]."]], "3": [["Q3", "NPP = 25 000 − 10 000 = 15 000; GSP = 2000 − 1200 = 800; NSP = 800 − 600 = 200."]], "4": [["Q4", "Energy is lost at each trophic level, so only about 10% of the energy in crops ends up in cattle [1]; eating crops directly at a lower trophic level makes much more energy available to people [1]."]], "5": [["Q5", "DDT is persistent and fat-soluble, so it is not broken down or excreted [1]; it accumulates in organisms and each predator eats many prey [1]; concentrations increase up the food chain, reaching the highest levels in top predators (biomagnification) [1]."]], "6": [["Exit ticket", "NPP = GPP − R."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0aecf3c5-57af-57e5-bf3d-1c95cbd31975', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '2.3' limit 1), '2.3 Biogeochemical cycles · Lesson 1: The carbon and nitrogen cycles and human impacts', 'IB DP ESS · 2.3 Biogeochemical cycles', '/ess23-lesson1/', 'ESS-23-L1', 19, 51 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-23-L1', '2.3 Biogeochemical cycles · Lesson 1: The carbon and nitrogen cycles and human impacts', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Photosynthesis", "Combustion", "Respiration", "Dissolving", "Sedimentation"], "tip": "Five flows."}, {"kind": "text", "id": "q1_1", "q": "Q2", "max": 3, "pts": [["dissolve", "absorb"], ["carbonic acid", "ph", "acid"], ["carbonate", "shell", "coral", "skeleton"]], "tips": ["Dissolving → acid → shells."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Nitrogen fixation", "Nitrification", "Ammonification", "Denitrification", "Assimilation"], "tip": "Follow nitrogen from air to soil and back."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 3, "pts": [["runoff", "leach"], ["algae", "algal bloom", "nitrate"], ["decompos", "oxygen", "bod", "dead zone"]], "tips": ["Runoff → algae → oxygen."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["fixing", "fixation", "rhizobium"], ["nitrifying", "nitrification", "nitrate"], ["denitrifying", "denitrification", "decompos", "ammonification"]], "tips": ["Three groups."]}]}, "models": {"1": [["Q1", "Photosynthesis; combustion; respiration; dissolving; sedimentation."], ["Q2", "Oceans absorb more CO₂ from the atmosphere [1]; it forms carbonic acid, lowering ocean pH (acidification) [1]; less carbonate is available, so corals and shellfish struggle to build skeletons and shells [1]."]], "2": [["Q3", "Fixation; nitrification; ammonification; denitrification; assimilation."]], "3": [["Q4", "Excess nitrate from fertiliser leaches or runs off into rivers and lakes [1]; it causes rapid growth of algae (algal blooms) [1]; when algae die, decomposers use up dissolved oxygen (high BOD), killing fish and creating dead zones [1]."]], "4": [["Q5", "Nitrogen-fixing bacteria such as Rhizobium convert N₂ to ammonium [1]; nitrifying bacteria convert ammonium to nitrite and nitrate [1]; denitrifying bacteria convert nitrate back to N₂, and decomposers release ammonium by ammonification [1]."]], "6": [["Exit ticket", "Peatland; draining or burning it. (Or forest; deforestation by burning.)"]]}, "labels": {"q1_1": "Q2", "q3_0": "Q4", "q4_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '8b349d31-f134-5e3e-b035-56dd9b277f4b', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '2.4' limit 1), '2.4 Climate and biomes · Lesson 1: Biomes, climographs, the tricellular model and shifting biomes', 'IB DP ESS · 2.4 Climate and biomes', '/ess24-lesson1/', 'ESS-24-L1', 14, 61 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-24-L1', '2.4 Climate and biomes · Lesson 1: Biomes, climographs, the tricellular model and shifting biomes', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Tropical rainforest", "Hot desert", "Tundra", "Taiga", "Savanna"], "tip": "Temperature and rainfall."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 2, "n": 2, "ans": ["Tropical rainforest", "Very high"], "tip": "Warm and wet all year."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["hadley"], ["sink", "descend", "high pressure"], ["dry", "no rain", "warm", "no condensation", "clouds"]], "tips": ["What does the air do at 30°?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["warm", "temperature", "permafrost"], ["taiga", "shrink", "poleward", "trees", "reduce"]], "tips": ["What moves into the tundra?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["insolation", "light", "warm", "temperature"], ["water", "rain", "growing season", "all year"]], "tips": ["Light, warmth, water, season."]}]}, "models": {"1": [["Q1", "Rainforest; desert; tundra; taiga; savanna."]], "2": [["Q2", "Tropical rainforest with very high NPP."]], "3": [["Q3", "In the Hadley cell, air that rose at the equator flows poleward [1] and sinks at about 30°, creating high pressure [1]; sinking air warms and dries, so there is little cloud or condensation and very little rain [1]."]], "4": [["Q4", "Rising temperatures thaw permafrost and lengthen the growing season [1]; taiga trees and shrubs spread poleward, so the tundra shrinks [1]."]], "5": [["Q5", "Rainforests receive high insolation and warm temperatures, so photosynthesis rates are high [1]; plentiful rain and a year-round growing season allow continuous growth, unlike the cold, short season of the tundra [1]."]], "6": [["Exit ticket", "The Hadley cell."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'f40d49e3-93c7-51e7-8fb8-24fadfebfd23', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '2.5' limit 1), '2.5 Zonation, succession and change in ecosystems · Lesson 1: Zonation, primary and secondary succession, climax communities', 'IB DP ESS · 2.5 Zonation, succession and change in ecosystems', '/ess25-lesson1/', 'ESS-25-L1', 16, 71 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-25-L1', '2.5 Zonation, succession and change in ecosystems · Lesson 1: Zonation, primary and secondary succession, climax communities', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["temperature", "colder"], ["precipitation", "rain", "wind", "soil", "oxygen", "uv"], ["adapt", "tolerance", "species", "growing season"]], "tips": ["Abiotic changes → species with different tolerances."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Primary", "Secondary", "Primary", "Secondary"], "tip": "Is there soil?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["early", "pioneer", "low"], ["increase", "gpp > r", "accumulat", "biomass"], ["climax", "gpp = r", "balance", "equal"]], "tips": ["Early, middle, climax."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 4, "n": 4, "ans": ["Plagioclimax", "Climax community", "Plagioclimax", "Plagioclimax"], "tip": "Is human activity holding it back?"}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["zonation+space", "zonation+gradient"], ["succession+time"]], "tips": ["Space vs time."]}]}, "models": {"1": [["Q1", "Temperature falls with altitude [1]; precipitation, wind exposure and soil depth also change [1]; species have different ranges of tolerance, so different communities form in different zones [1]."]], "2": [["Q2", "Lava and glacier: primary. Field and wildfire: secondary."]], "3": [["Q3", "Early stages have low GPP because of little vegetation [1]; GPP rises and exceeds respiration so biomass accumulates [1]; at climax GPP is high but roughly equal to respiration, so net productivity is low and biomass is stable [1]."]], "4": [["Q4", "Grazed grassland, burned moorland and tea plantation: plagioclimax. Rainforest: climax."]], "5": [["Q5", "Zonation is the change in communities across space along an environmental gradient [1]; succession is the change in communities over time at one place [1]."]], "6": [["Exit ticket", "A community where succession has been stopped by human activity before reaching the climax."]]}, "labels": {"q1_0": "Q1", "q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '18530ec7-ec11-5134-a18b-c53b2d726a76', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '3.1' limit 1), '3.1 Biodiversity and evolution · Lesson 1: Components of biodiversity, natural selection, speciation and mass extinctions', 'IB DP ESS · 3.1 Biodiversity and evolution', '/ess31-lesson1/', 'ESS-31-L1', 15, 81 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-31-L1', '3.1 Biodiversity and evolution · Lesson 1: Components of biodiversity, natural selection, speciation and mass extinctions', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Genetic diversity", "Species diversity", "Habitat diversity", "Genetic diversity"], "tip": "Within a species, between species, or between habitats?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["barrier", "isolat", "separate"], ["different selection", "different environment", "selection pressures"], ["allele", "adapt", "natural selection", "variation"], ["cannot interbreed", "no longer interbreed", "fertile"]], "tips": ["Barrier → selection → change → no interbreeding."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["isolat", "separate", "barrier", "speciation"], ["habitat", "mountain", "island", "climate", "land bridge", "mix"]], "tips": ["Separating and creating."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["insolation", "warm", "light", "energy"], ["productivity", "npp", "resources"], ["stable", "time", "habitat", "niche", "complex"]], "tips": ["Energy, productivity, stability."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["variation", "alleles", "different"], ["adapt", "survive", "disease", "change", "resist"]], "tips": ["Change in environment."]}]}, "models": {"1": [["Q1", "Cheetah alleles and maize varieties: genetic. Reef species: species. Park habitats: habitat diversity."]], "2": [["Q2", "A geographic barrier such as a sea or mountain range separates a population [1]; each group faces different selection pressures [1]; natural selection changes allele frequencies so the groups adapt differently [1]; eventually they can no longer interbreed to produce fertile offspring, forming new species [1]."]], "3": [["Q3", "Moving continents separated populations, leading to isolation and speciation [1]; they created new habitats such as mountains and islands, changed climates, or joined land masses so species mixed [1]."]], "4": [["Q4", "Tropical regions receive high insolation and are warm all year [1], so productivity is high and more resources support more species [1]; stable climates over long periods and complex habitats create many niches for speciation [1]."]], "5": [["Q5", "Genetic diversity means there is variation in alleles within the population [1], so some individuals may survive environmental change or new diseases, allowing the species to adapt [1]."]], "6": [["Exit ticket", "Genetic, species and habitat diversity."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'a33717ee-3280-5b43-877b-3924650123ac', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '3.2' limit 1), '3.2 Human impact on biodiversity · Lesson 1: Threats to biodiversity, extinction risk and the IUCN Red List', 'IB DP ESS · 3.2 Human impact on biodiversity', '/ess32-lesson1/', 'ESS-32-L1', 18, 91 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-32-L1', '3.2 Human impact on biodiversity · Lesson 1: Threats to biodiversity, extinction risk and the IUCN Red List', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Overexploitation", "Invasive species", "Habitat loss", "Pollution", "Overexploitation"], "tip": "H, I, P, P, O."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["small population", "few", "1000"], ["slow reproduction", "k-strategist", "one infant", "long"], ["habitat", "range", "restricted", "poach", "disease"]], "tips": ["Numbers, breeding, range."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["1", "2", "3", "4", "5"], "tip": "LC → CR."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["nutrient", "thin soil", "poor soil", "leach"], ["biomass", "slow", "erosion", "seed", "species lost"]], "tips": ["Where are the nutrients stored?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["population size", "number of mature"], ["decline", "rate"], ["range", "area", "fragment", "distribution"]], "tips": ["Size, decline, range."]}]}, "models": {"1": [["Q1", "Poaching and overfishing: overexploitation. Nile perch: invasive species. Oil palm: habitat loss. Microplastics: pollution."]], "2": [["Q2", "Mountain gorillas have a small population of about 1000 [1]; they are K-strategists with slow reproduction, having one infant every few years [1]; they live in a restricted range of forest threatened by habitat loss, poaching and human diseases [1]."]], "3": [["Q3", "LC 1, NT 2, VU 3, EN 4, CR 5."]], "4": [["Q4", "Most nutrients are stored in the biomass, and the thin soils are nutrient-poor and quickly leached once trees are removed [1]; erosion and loss of seed sources and species mean regrowth is very slow [1]."]], "5": [["Q5", "Population size (number of mature individuals) [1]; rate of population decline [1]; geographic range and degree of fragmentation [1]."]], "6": [["Exit ticket", "Habitat loss, Invasive species, Pollution, Population growth, Overexploitation."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '8b979365-181d-5e5f-bbda-513d7f477079', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '3.3' limit 1), '3.3 Conservation and regeneration · Lesson 1: In situ and ex situ conservation, protected area design and rewilding', 'IB DP ESS · 3.3 Conservation and regeneration', '/ess33-lesson1/', 'ESS-33-L1', 18, 101 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-33-L1', '3.3 Conservation and regeneration · Lesson 1: In situ and ex situ conservation, protected area design and rewilding', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Ethical", "Economic", "Ecological", "Cultural/aesthetic"], "tip": "Money, ecosystem function, rights, culture."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["in situ+natural habitat", "in situ+ecosystem", "in situ+park"], ["ex situ+zoo", "ex situ+seed bank", "ex situ+outside", "ex situ+captive"], ["in situ+interaction", "in situ+whole", "in situ+adapt", "in situ+many species"], ["ex situ+genetic", "ex situ+expensive", "ex situ+critically", "ex situ+behaviour", "ex situ+reintroduc"]], "tips": ["Where, and one strength or weakness of each."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 2, "pts": [["connect", "link", "move", "migrat"], ["gene flow", "genetic diversity", "inbreeding", "larger population", "interbreed"]], "tips": ["Movement and genes."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Flagship species", "Keystone species", "Umbrella species", "CITES", "Rewilding"], "tip": "One each."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["flagship", "awareness", "funds", "public"], ["ignore", "other species", "habitat", "expensive", "only one"], ["combine", "habitat", "conclusion", "best"]], "tips": ["Strength, limitation, judgement."]}]}, "models": {"1": [["Q1", "Ethical; economic; ecological; cultural."]], "2": [["Q2", "In situ conservation protects species in their natural habitat, such as national parks [1], whereas ex situ conservation keeps them outside it, in zoos or seed banks [1]; in situ protects whole ecosystems and many species with their interactions [1]; ex situ can save critically endangered species and genetic material for reintroduction but is expensive and captive animals may lose natural behaviour [1]."]], "3": [["Q3", "Corridors connect isolated habitat fragments so animals can move and migrate between them [1]; this allows gene flow between populations, increasing genetic diversity and reducing inbreeding [1]."]], "4": [["Q4", "Flagship; keystone; umbrella; CITES; rewilding."]], "5": [["Q5", "Focusing on flagship species raises public awareness and funds [1]; however it may ignore less charismatic species and the wider habitat, and can be expensive [1]; it works best when combined with habitat protection, for example umbrella species whose protection conserves whole ecosystems [1]."]], "6": [["Exit ticket", "Less edge relative to area, so smaller edge effects."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'c178b51a-fda1-51cd-b845-8809fbdc8cc8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '4.1' limit 1), '4.1 Water systems · Lesson 1: The hydrological cycle, water stores, ocean circulation and human impacts', 'IB DP ESS · 4.1 Water systems', '/ess41-lesson1/', 'ESS-41-L1', 12, 111 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-41-L1', '4.1 Water systems · Lesson 1: The hydrological cycle, water stores, ocean circulation and human impacts', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Transformation", "Transfer", "Transformation", "Transfer", "Transformation"], "tip": "Change of state?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["nutrient", "nitrate", "phosphate"], ["phytoplankton", "photosynthesis", "food web", "fish"]], "tips": ["What comes up from the deep?"]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["impermeable", "concrete", "tarmac"], ["infiltration"], ["runoff", "drain", "faster", "peak"]], "tips": ["Surface → infiltration → runoff."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["residence time", "slow", "long time"], ["not replaced", "not flushed", "dilut", "years", "centuries"]], "tips": ["Residence time."]}]}, "models": {"1": [["Q1", "Evaporation, condensation, melting: transformations. Runoff, infiltration: transfers."]], "2": [["Q2", "Upwelling brings cold, nutrient-rich water from the deep ocean to the surface [1], so phytoplankton grow rapidly in sunlight, supporting large food webs and fisheries [1]."]], "3": [["Q3", "Urban areas have impermeable surfaces such as concrete and tarmac [1], which reduce infiltration into the soil [1]; more water becomes surface runoff and is carried quickly by drains to rivers, raising peak discharge and flood risk [1]."]], "4": [["Q4", "Groundwater has a long residence time because it moves very slowly through rock [1], so pollutants are not quickly flushed or diluted and can persist for years or centuries [1]."]], "6": [["Exit ticket", "Precipitation and surface runoff (also infiltration, percolation, river flow)."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '681a55c8-2c09-5b69-bc3d-3207ba239318', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '4.2' limit 1), '4.2 Water access, use and security · Lesson 1: Water scarcity, water footprints, management and conflict', 'IB DP ESS · 4.2 Water access, use and security', '/ess42-lesson1/', 'ESS-42-L1', 13, 121 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-42-L1', '4.2 Water access, use and security · Lesson 1: Water scarcity, water footprints, management and conflict', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Economic", "Physical", "Economic", "Physical"], "tip": "Not enough water, or no means to access it?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["meat", "beef", "diet"], ["clothes", "shower", "waste", "less", "buy", "fewer"]], "tips": ["Direct and virtual water."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["reliable", "unlimited", "drought", "sea water"], ["energy", "expensive", "cost", "brine", "fossil fuel"], ["conclusion", "suitable", "wealthy", "renewable", "coastal"]], "tips": ["Strength, limitation, judgement."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["upstream", "control"], ["downstream", "less water", "reduce", "flow"]], "tips": ["Who controls the water?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["physical+not enough", "physical+insufficient", "physical+lack of water"], ["economic+infrastructure", "economic+money", "economic+afford", "economic+access"]], "tips": ["Availability vs access."]}]}, "models": {"1": [["Q1", "No pipes and unaffordable water: economic. Desert and depleted aquifers: physical."]], "2": [["Q2", "Eat less meat, especially beef, which has a very large virtual water footprint [1]; buy fewer new clothes and reduce direct water use, such as shorter showers and fixing leaks [1]."]], "3": [["Q3", "Desalination gives a reliable supply independent of rainfall, useful in drought [1]; however it is expensive and energy-intensive, often using fossil fuels, and produces brine that harms marine life [1]; it suits wealthy coastal countries, especially if powered by renewable energy [1]."]], "4": [["Q4", "The upstream country controls how much water is stored and released [1], so downstream countries may receive less water for drinking and farming, especially when the reservoir is being filled [1]."]], "5": [["Q5", "Physical scarcity occurs when there is not enough water to meet demand [1]; economic scarcity occurs when water is available but people lack the money or infrastructure to access it [1]."]], "6": [["Exit ticket", "Supply: desalination or dams. Demand: drip irrigation or fixing leaks."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '79e3d231-d367-5782-972d-07723f4c86a8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '4.3' limit 1), '4.3 Aquatic food production systems · Lesson 1: Fisheries, overfishing, maximum sustainable yield and aquaculture', 'IB DP ESS · 4.3 Aquatic food production systems', '/ess43-lesson1/', 'ESS-43-L1', 16, 131 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-43-L1', '4.3 Aquatic food production systems · Lesson 1: Fisheries, overfishing, maximum sustainable yield and aquaculture', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["technology", "factory", "trawl", "sonar"], ["catch", "more than", "exceed", "overfish"], ["reproduc", "breed", "replace", "young", "immature"]], "tips": ["Technology, catch rate, recovery."]}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["K/2", "Population declines", "Population stays the same"], "tip": "Steepest part of the S-curve."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Minimum mesh size", "Quota", "Marine protected area", "Eco-label", "Closed season"], "tip": "One each."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["reduce pressure", "wild stock", "supply", "protein"], ["mangrove", "pollution", "disease", "escape", "fishmeal", "antibiotic"], ["conclusion", "herbivor", "tilapia", "sustainable if", "managed"]], "tips": ["Strength, limitation, judgement."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["no one owns", "open access", "shared", "common"], ["each", "individual", "overuse", "overexploit", "depleted"]], "tips": ["Shared resource, individual gain."]}]}, "models": {"1": [["Q1", "Large trawlers with sonar technology greatly increased fishing pressure [1]; catches exceeded the rate at which the stock could replace itself [1]; too few mature fish were left to breed, so the population collapsed [1]."]], "2": [["Q2", "MSY at K/2; catching more than MSY reduces the stock; catching the annual growth keeps it stable."]], "3": [["Q3", "Mesh size; quota; MPA; eco-label; closed season."]], "4": [["Q4", "Aquaculture can reduce pressure on wild stocks and provide a reliable supply of protein [1]; however it can destroy mangroves, cause pollution and disease, and carnivorous fish need fishmeal from wild fish [1]; it is sustainable if managed well, for example farming herbivorous species like tilapia with waste treatment [1]."]], "5": [["Q5", "Open-ocean fish stocks are shared, open-access resources that no one owns [1]; each fisher gains by catching more, so collectively the resource is overused and depleted [1]."]], "6": [["Exit ticket", "The largest catch that can be taken each year without reducing the stock over time."]]}, "labels": {"q1_0": "Q1", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'bbe5ab12-5bda-5128-a569-5f4ff6c99d4d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '4.4' limit 1), '4.4 Water pollution · Lesson 1: Sources of pollution, measuring water quality, eutrophication and management', 'IB DP ESS · 4.4 Water pollution', '/ess44-lesson1/', 'ESS-44-L1', 22, 141 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-44-L1', '4.4 Water pollution · Lesson 1: Sources of pollution, measuring water quality, eutrophication and management', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Point source", "Non-point source", "Non-point source", "Point source"], "tip": "Single pipe or spread out?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Clean water", "Polluted water", "Clean water", "Polluted water", "Polluted water"], "tip": "Oxygen demand."}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["organic", "sewage"], ["bacteria", "decompos", "microorganism"], ["respir", "use oxygen", "bod"]], "tips": ["Food for decomposers."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["1", "2", "3", "4", "5"], "tip": "Nutrients → algae → death → decomposers."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q5", "max": 3, "pts": [["less fertiliser", "phosphate-free", "organic", "detergent", "alter"], ["buffer", "sewage treatment", "regulat", "release"], ["dredg", "remove algae", "aerat", "clean", "restor"]], "tips": ["One for each level."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["oxygen", "microorganism", "bacteria"], ["organic", "decompos", "5 days", "five days"]], "tips": ["Who uses oxygen, doing what, over what time."]}]}, "models": {"1": [["Q1", "Factory pipe and sewage outfall: point. Farm and urban runoff: non-point."]], "2": [["Q2", "Stoneflies and mayflies: clean. Bloodworms, sludgeworms, high BOD: polluted."], ["Q3", "Sewage adds large amounts of organic matter [1]; bacteria decompose it [1]; their aerobic respiration uses up dissolved oxygen, giving a high BOD and low oxygen [1]."]], "3": [["Q4", "Nutrients; algal bloom; death; decomposition; fish die."]], "4": [["Q5", "Alter human activity by using less fertiliser or phosphate-free detergents [1]; regulate release by planting buffer strips along rivers and improving sewage treatment [1]; clean up by dredging nutrient-rich sediment, removing algae or aerating the water [1]."]], "5": [["Q6", "BOD is the amount of dissolved oxygen used by microorganisms [1] to decompose the organic matter in a water sample over 5 days at 20 °C [1]."]], "6": [["Exit ticket", "Altering human activity, because it stops the pollutant being produced in the first place."]]}, "labels": {"q2_1": "Q3", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '1dc0bdcb-416e-5916-bbcb-1aff3fd568b1', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '5.1' limit 1), '5.1 Soil · Lesson 1: Soil as a system, soil profiles, texture, degradation and conservation', 'IB DP ESS · 5.1 Soil', '/ess51-lesson1/', 'ESS-51-L1', 19, 151 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-51-L1', '5.1 Soil · Lesson 1: Soil as a system, soil profiles, texture, degradation and conservation', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Input", "Output", "Transfer", "Transformation", "Transformation"], "tip": "Entering, leaving, moving or changing?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Sandy soil", "Clay soil", "Loam", "Clay soil"], "tip": "Particle size."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["vegetation", "plant cover", "grass removed"], ["bare", "exposed", "roots"], ["wind", "rain", "runoff", "wash", "blow"]], "tips": ["Cover → bare → agents."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Windbreak", "Terracing", "Contour ploughing", "Cover crop", "Crop rotation"], "tip": "One each."}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["drain", "aerat", "air"], ["water", "nutrient", "retain", "hold"]], "tips": ["Best of sand and clay."]}]}, "models": {"1": [["Q1", "Leaves: input. Leaching: output. Earthworms: transfer. Decomposition and weathering: transformations."]], "2": [["Q2", "Sandy: drains quickly. Clay: waterlogged, compacts, small particles hold nutrients. Loam: best balance."]], "3": [["Q3", "Too many animals remove the vegetation cover [1], leaving the soil bare and no longer bound by roots [1]; wind and rain runoff can then easily blow or wash the topsoil away [1]."]], "4": [["Q4", "Windbreak; terracing; contour ploughing; cover crop; crop rotation."]], "5": [["Q5", "Loam has enough sand for good drainage and aeration of roots [1], and enough clay and humus to retain water and nutrients [1]."]], "6": [["Exit ticket", "Lost: erosion by water or wind. Conserved: terracing, contour ploughing or cover crops."]]}, "labels": {"q3_0": "Q3", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '849f6cc1-0560-5827-bf15-23150f3affce', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '5.2' limit 1), '5.2 Agriculture and food · Lesson 1: Food systems, environmental impacts and sustainable agriculture', 'IB DP ESS · 5.2 Agriculture and food', '/ess52-lesson1/', 'ESS-52-L1', 17, 161 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-52-L1', '5.2 Agriculture and food · Lesson 1: Food systems, environmental impacts and sustainable agriculture', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Extensive", "Intensive", "Intensive", "Extensive"], "tip": "Inputs per hectare."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["trophic", "10%", "energy lost"], ["land", "water", "feed"], ["methane", "greenhouse", "deforest"]], "tips": ["Trophic levels, resources, emissions."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Post-harvest and storage", "Retail and consumers", "Retail and consumers", "Post-harvest and storage"], "tip": "Early or late in the supply chain?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["no synthetic", "less pollution", "biodiversity", "soil"], ["lower yield", "more land", "expensive"], ["conclusion", "combine", "depends", "overall"]], "tips": ["Strength, limitation, judgement."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 3, "pts": [["intensive+high input", "intensive+fertiliser", "intensive+machinery"], ["extensive+large area", "extensive+low input"], ["yield", "per hectare", "pollution", "impact"]], "tips": ["Inputs, land, yield."]}]}, "models": {"1": [["Q1", "Pastoralism and nomadic herding: extensive. Greenhouses and battery farms: intensive."]], "2": [["Q2", "Energy is lost between trophic levels, so far more crops are needed to feed cattle than to feed people directly [1]; beef therefore needs much more land and water per kilogram [1]; cattle also produce methane and pasture expansion causes deforestation [1]."]], "3": [["Q3", "Weevils and transport without refrigeration: post-harvest. Supermarket and household waste: retail and consumer."]], "4": [["Q4", "Organic farming avoids synthetic fertilisers and pesticides, reducing pollution and supporting soil health and biodiversity [1]; however yields are often lower, so more land may be needed, and produce is more expensive [1]; overall it is more sustainable when combined with less food waste and lower meat consumption [1]."]], "5": [["Q5", "Intensive farming uses high inputs such as fertilisers, pesticides and machinery [1], whereas extensive farming uses low inputs over a large area [1]; intensive systems give higher yields per hectare but cause more pollution [1]."]], "6": [["Exit ticket", "Any two: crop rotation with legumes, agroforestry, IPM/push–pull, cover crops, no-till."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b80b980f-27ae-5d9d-8e4e-5af2aa3c0686', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '6.1' limit 1), '6.1 Introduction to the atmosphere · Lesson 1: Composition, structure, the natural greenhouse effect and albedo', 'IB DP ESS · 6.1 Introduction to the atmosphere', '/ess61-lesson1/', 'ESS-61-L1', 14, 171 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-61-L1', '6.1 Introduction to the atmosphere · Lesson 1: Composition, structure, the natural greenhouse effect and albedo', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Troposphere", "Stratosphere", "Troposphere", "Stratosphere"], "tip": "Weather below, ozone above."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["short-wave", "short wave", "solar radiation"], ["long-wave", "long wave", "infrared"], ["absorb", "greenhouse gas"], ["re-emit", "back", "warm", "15"]], "tips": ["In, out, trapped, result."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["High albedo", "Low albedo", "Low albedo", "High albedo"], "tip": "Light colours reflect."}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["albedo", "reflect"], ["ocean", "darker", "absorb", "more energy"]], "tips": ["Ice → water."]}]}, "models": {"1": [["Q1", "Weather and lowest: troposphere. Ozone and warming with height: stratosphere."]], "2": [["Q2", "Short-wave solar radiation passes through the atmosphere and warms Earth''s surface [1]; the surface emits long-wave infrared radiation [1]; greenhouse gases such as CO₂ and water vapour absorb it [1]; they re-emit it, some back towards the surface, keeping Earth about 33 °C warmer, at about 15 °C [1]."]], "3": [["Q3", "Snow and cloud: high. Ocean and tarmac: low."]], "4": [["Q4", "Sea ice has a high albedo and reflects most sunlight [1]; when it melts, darker ocean with low albedo is exposed and absorbs much more energy [1]."]], "6": [["Exit ticket", "Any two: water vapour, carbon dioxide, methane, nitrous oxide, ozone."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '4d90b57b-a155-506f-bd59-957c60aab2f3', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '6.2' limit 1), '6.2 Climate change—causes and impacts · Lesson 1: The enhanced greenhouse effect, evidence, feedbacks and impacts', 'IB DP ESS · 6.2 Climate change—causes and impacts', '/ess62-lesson1/', 'ESS-62-L1', 15, 181 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-62-L1', '6.2 Climate change—causes and impacts · Lesson 1: The enhanced greenhouse effect, evidence, feedbacks and impacts', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Carbon dioxide", "Methane", "Nitrous oxide", "Halocarbons"], "tip": "One each."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["keeling", "co2 rise", "315", "420", "ice core"], ["temperature", "glacier", "sea level", "sea ice", "warming"]], "tips": ["CO₂ records and temperature records."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Positive feedback", "Negative feedback", "Positive feedback", "Positive feedback"], "tip": "Amplify or reduce warming?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["emission", "contributed least", "historical"], ["vulnerable", "agriculture", "drought", "coast", "exposure"], ["adapt", "money", "resources", "infrastructure", "capacity"]], "tips": ["Responsibility, exposure, capacity."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["natural+keeps", "natural+15", "natural+life", "natural+warm"], ["enhanced+human", "enhanced+anthropogenic", "enhanced+increase", "enhanced+additional"]], "tips": ["Natural vs human-caused."]}]}, "models": {"1": [["Q1", "CO₂: coal. CH₄: cattle and rice. N₂O: fertiliser. Halocarbons: refrigerants."]], "2": [["Q2", "The Keeling Curve shows atmospheric CO₂ rising from 315 ppm in 1958 to over 420 ppm, far above the ice core range [1]; global temperatures have risen about 1.2 °C, with shrinking glaciers and sea ice [1]."]], "3": [["Q3", "Permafrost, water vapour, ice–albedo: positive. CO₂ fertilisation: negative."]], "4": [["Q4", "Low-income countries have contributed least to historical emissions [1]; many are more exposed, depending on rain-fed agriculture or low-lying coasts [1]; they have less money and infrastructure to adapt [1]."]], "5": [["Q5", "The natural greenhouse effect is caused by naturally occurring gases and keeps Earth warm enough for life, at about 15 °C [1]; the enhanced greenhouse effect is the additional warming caused by human emissions increasing greenhouse gas concentrations [1]."]], "6": [["Exit ticket", "Far more CO₂ is emitted and it stays in the atmosphere much longer."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '5a33cd69-85ee-5cad-97ef-4f68a6d6222d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '6.3' limit 1), '6.3 Climate change—mitigation and adaptation · Lesson 1: Mitigation, adaptation, geoengineering and international agreements', 'IB DP ESS · 6.3 Climate change—mitigation and adaptation', '/ess63-lesson1/', 'ESS-63-L1', 18, 191 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-63-L1', '6.3 Climate change—mitigation and adaptation · Lesson 1: Mitigation, adaptation, geoengineering and international agreements', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Reducing emissions", "Increasing sinks", "Increasing sinks", "Reducing emissions", "Increasing sinks"], "tip": "Less going in, or more coming out?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Adaptation", "Adaptation", "Mitigation", "Adaptation", "Mitigation"], "tip": "Causes or impacts?"}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["reflect", "cool", "quick", "fast"], ["side effect", "rainfall", "ozone", "acid", "termination", "uneven"], ["not reduce co2", "acidification", "moral hazard", "governance", "conclusion"]], "tips": ["Benefit, risk, judgement."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["kyoto+developed", "kyoto+binding"], ["paris+all", "paris+every country", "paris+ndc"], ["paris+not binding", "paris+voluntary", "paris+1.5", "both"]], "tips": ["Who, how binding, aims."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["mitigation+reduc", "mitigation+emission"], ["adaptation+adjust", "adaptation+impact", "adaptation+sea wall", "adaptation+drought"]], "tips": ["Causes vs impacts."]}]}, "models": {"1": [["Q1", "Geothermal and buses: reducing emissions. Mangroves, direct air capture and peatlands: increasing sinks."]], "2": [["Q2", "Sorghum, sea wall, early warning: adaptation. Solar panels, carbon tax: mitigation."]], "3": [["Q3", "Injecting aerosols could reflect sunlight and cool the planet quickly [1]; however it may change rainfall patterns unevenly, damage ozone, and cause rapid warming if stopped (termination shock) [1]; it does not reduce CO₂ or ocean acidification and may reduce motivation to cut emissions, so it should not replace mitigation [1]."]], "4": [["Q4", "Kyoto set legally binding targets for developed countries only [1]; Paris requires all countries to set their own nationally determined contributions [1]; Paris targets are voluntary and not legally binding, aiming to limit warming to well below 2 °C and pursue 1.5 °C [1]."]], "5": [["Q5", "Mitigation reduces the causes of climate change by cutting emissions or increasing sinks, e.g. renewable energy [1]; adaptation adjusts to reduce the impacts, e.g. sea walls or drought-tolerant crops [1]."]], "6": [["Exit ticket", "Mitigation: geothermal power. Adaptation: drought-tolerant crops or water harvesting."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '37faadd2-778d-5362-8ca1-5188f0c78a80', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '6.4' limit 1), '6.4 Stratospheric ozone · Lesson 1: The ozone layer, ozone-depleting substances and the Montreal Protocol', 'IB DP ESS · 6.4 Stratospheric ozone', '/ess64-lesson1/', 'ESS-64-L1', 11, 201 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-64-L1', '6.4 Stratospheric ozone · Lesson 1: The ozone layer, ozone-depleting substances and the Montreal Protocol', '{"marks": {"1": [{"kind": "text", "id": "q1_0", "q": "Q1", "max": 3, "pts": [["skin cancer", "cataract", "eye"], ["immune", "dna", "mutation"], ["phytoplankton", "crop", "plant", "productivity"]], "tips": ["Humans, cells, ecosystems."]}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["uv", "break down", "stratosphere"], ["chlorine"], ["catalyst", "regenerat", "many", "100 000"]], "tips": ["Release → react → regenerate."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["substitute", "alternative", "replacement"], ["few", "small number", "producers", "industr"], ["fund", "financial", "binding", "sanction", "science", "clear"]], "tips": ["Alternatives, number of sources, support."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["cold", "polar stratospheric clouds", "winter"], ["sunlight", "spring", "uv", "return"]], "tips": ["Winter clouds, spring sunlight."]}]}, "models": {"1": [["Q1", "In humans, more UV increases skin cancer and cataracts [1]; it damages DNA and suppresses the immune system [1]; it reduces crop yields and kills phytoplankton, lowering marine productivity [1]."]], "2": [["Q2", "In the stratosphere, UV radiation breaks down CFC molecules [1], releasing chlorine atoms that react with ozone, converting it to oxygen [1]; the chlorine is regenerated, acting as a catalyst, so one atom can destroy many thousands of ozone molecules [1]."]], "3": [["Q3", "Cheap substitutes for CFCs were available [1]; ODS were made by a small number of producers in a few industries, unlike CO₂ which comes from the whole economy [1]; the protocol was legally binding with trade sanctions, clear science, and a fund to help developing countries [1]."]], "4": [["Q4", "Very cold winter temperatures form polar stratospheric clouds, on which chlorine is converted into reactive forms [1]; when sunlight returns in spring, it drives rapid destruction of ozone [1]."]], "6": [["Exit ticket", "The Montreal Protocol."]]}, "labels": {"q1_0": "Q1", "q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'b9cec47d-e60f-55a9-9e8b-fcab5a5b9653', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '7.1' limit 1), '7.1 Natural resources—uses and management · Lesson 1: Types of resources, resource security and sustainable management', 'IB DP ESS · 7.1 Natural resources—uses and management', '/ess71-lesson1/', 'ESS-71-L1', 12, 211 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-71-L1', '7.1 Natural resources—uses and management · Lesson 1: Types of resources, resource security and sustainable management', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Renewable", "Replenishable", "Non-renewable", "Non-renewable", "Renewable"], "tip": "Living, non-living but replaced, or finite?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 2, "pts": [["technology", "new use", "invent"], ["culture", "economic", "demand", "replace", "lithium", "uranium"]], "tips": ["New uses and new substitutes."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["reuse", "repair", "recycl", "remanufactur"], ["less", "reduce", "demand", "extraction", "virgin"], ["waste", "kept in use", "security", "supply"]], "tips": ["Keep materials in use."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["faster", "exceed", "rate", "overuse"], ["replac", "regenerat", "natural income", "capital"]], "tips": ["Use vs replacement rate."]}]}, "models": {"1": [["Q1", "Timber and fish: renewable. Groundwater: replenishable. Oil and cobalt: non-renewable."]], "2": [["Q2", "New technology can create new uses for a resource, e.g. lithium became valuable for batteries [1]; changes in culture, demand or substitutes can reduce or increase value [1]."]], "3": [["Q3", "A circular economy keeps materials in use by reuse, repair and recycling [1]; this reduces the demand for extracting new raw materials [1]; less waste and a more secure supply of materials result, reducing dependence on imports [1]."]], "4": [["Q4", "If a renewable resource is used faster than it can regenerate [1], the natural capital is reduced instead of only harvesting natural income, so it becomes depleted, e.g. overfishing [1]."]], "6": [["Exit ticket", "Lithium (batteries), uranium (nuclear power) or whale oil (replaced by kerosene)."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '0b532416-2363-5e81-a3b1-445e223718ef', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '7.2' limit 1), '7.2 Energy sources—uses and management · Lesson 1: Renewable and non-renewable energy, energy security and energy choices', 'IB DP ESS · 7.2 Energy sources—uses and management', '/ess72-lesson1/', 'ESS-72-L1', 16, 221 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-72-L1', '7.2 Energy sources—uses and management · Lesson 1: Renewable and non-renewable energy, energy security and energy choices', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Nuclear", "Geothermal", "Solar", "Coal", "Hydroelectric"], "tip": "One each."}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 4, "pts": [["availability", "geology", "local", "resources"], ["geothermal", "coal", "sun", "wind", "example"], ["cost", "economic", "political", "public", "security", "import"], ["affordable", "investment", "opinion", "depend", "fukushima", "conflict"]], "tips": ["Factor + explanation, twice."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Efficiency", "Conservation (using less)", "Storage", "Efficiency"], "tip": "Same service with less energy, less service, or saving for later?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["low carbon", "low emission", "reliable", "base load"], ["waste", "radioactive", "accident", "expensive", "cost"], ["conclusion", "transition", "depends", "overall"]], "tips": ["Strength, limitation, judgement."]}]}, "models": {"1": [["Q1", "Nuclear; geothermal; solar; coal; hydroelectric."]], "2": [["Q2", "Availability of local resources [1]: Kenya uses geothermal energy because it sits on the Rift Valley, while South Africa has large coal reserves [1]. Political and security concerns [1]: countries reduce dependence on imported fuels to avoid price shocks and conflict, and public opinion can stop nuclear power, as in Germany after Fukushima [1]."]], "3": [["Q3", "LEDs and insulation: efficiency. Turning off lights: conservation. Pumped hydro: storage."]], "4": [["Q4", "Nuclear power provides reliable, low-carbon base-load electricity [1]; however it produces long-lived radioactive waste, has accident risks and is very expensive and slow to build [1]; overall it can help the transition away from fossil fuels where countries can manage the waste and costs [1]."]], "6": [["Exit ticket", "They only generate when the sun shines or wind blows, so storage or backup is needed."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'd3a23e17-d1ce-5fec-9a64-05ade737fcfe', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '7.3' limit 1), '7.3 Solid waste · Lesson 1: Types of waste, the waste hierarchy and disposal options', 'IB DP ESS · 7.3 Solid waste', '/ess73-lesson1/', 'ESS-73-L1', 15, 231 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-73-L1', '7.3 Solid waste · Lesson 1: Types of waste, the waste hierarchy and disposal options', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Biodegradable", "Recyclable", "E-waste", "Hazardous"], "tip": "Rots, recycles, electronic or dangerous?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Reuse", "Reduce", "Recycle", "Recover", "Dispose"], "tip": "Top to bottom."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["landfill+cheap", "landfill+land", "landfill+leachate", "landfill+methane"], ["incineration+volume", "incineration+energy", "incineration+electricity"], ["incineration+air pollution", "incineration+expensive", "incineration+ash", "incineration+co2", "both"]], "tips": ["Cost, land, pollution, energy."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["ban", "reduce", "alter", "reusable", "tax"], ["recycl", "collect", "deposit", "regulat"], ["clean", "beach", "remove", "restor"]], "tips": ["Change activity, control release, clean up."]}]}, "models": {"1": [["Q1", "Banana peels: biodegradable. Cans: recyclable. Laptop: e-waste. Batteries: hazardous."]], "2": [["Q2", "Refill: reuse. Bag ban: reduce. Glass: recycle. Energy from waste: recover. Landfill: dispose."]], "3": [["Q3", "Landfill is cheap but uses large areas of land and produces leachate and methane [1]; incineration reduces waste volume by about 90% and can generate electricity [1]; but incineration is expensive and produces air pollution, CO₂ and toxic ash [1]."]], "4": [["Q4", "Alter human activity by banning single-use plastic bags or using reusable containers [1]; control release through collection, deposit schemes and recycling [1]; clean up through beach and river clean-ups to remove plastics already in the environment [1]."]], "6": [["Exit ticket", "Reuse."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '6630be3b-ef93-59af-b648-dabd42ad04b8', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '8.1' limit 1), '8.1 Human populations · Lesson 1: Population dynamics, the demographic transition model and population policies', 'IB DP ESS · 8.1 Human populations', '/ess81-lesson1/', 'ESS-81-L1', 13, 241 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-81-L1', '8.1 Human populations · Lesson 1: Population dynamics, the demographic transition model and population policies', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 2, "n": 2, "ans": ["2%", "35 years"], "tip": "(30 − 10) ÷ 10; 70 ÷ NIR."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 3, "n": 3, "ans": ["Wide base, narrow top", "Narrow base, wide top", "Straight sides"], "tip": "Base = births."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["education", "women", "career"], ["contracept", "family planning"], ["infant mortality", "urban", "cost", "children survive"]], "tips": ["Women, contraception, child survival."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["more people", "demand", "resources", "population"], ["consumption", "affluence", "technology", "footprint", "rich"], ["conclusion", "both", "depends"]], "tips": ["Population vs consumption."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["europe", "western", "based on"], ["migration", "not apply", "different", "timing", "stuck", "faster"]], "tips": ["Where did the data come from?"]}]}, "models": {"1": [["Q1", "NIR = (30 − 10) ÷ 10 = 2%; doubling time = 70 ÷ 2 = 35 years."]], "2": [["Q2", "High births: wide base. Ageing: narrow base. Stable: straight sides."]], "3": [["Q3", "More women are educated and enter paid work, so they marry and have children later [1]; contraception and family planning become widely available [1]; lower infant mortality, urbanisation and the high cost of raising children mean families choose fewer children [1]."]], "4": [["Q4", "More people increase demand for land, water, food and energy [1]; however consumption per person and technology matter as much: high-income countries with small populations have much larger footprints [1]; so impact depends on both population and consumption, not population alone [1]."]], "5": [["Q5", "The model is based on the experience of European countries [1], so it may not apply to other countries, and it ignores migration and differences in timing [1]."]], "6": [["Exit ticket", "70 ÷ 1.4 = 50 years."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '179333f5-1eb1-5880-a34d-acd1961dd308', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '8.2' limit 1), '8.2 Urban systems and urban planning · Lesson 1: Urbanisation, cities as systems and sustainable urban planning', 'IB DP ESS · 8.2 Urban systems and urban planning', '/ess82-lesson1/', 'ESS-82-L1', 12, 251 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-82-L1', '8.2 Urban systems and urban planning · Lesson 1: Urbanisation, cities as systems and sustainable urban planning', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Push factor", "Pull factor", "Pull factor", "Push factor"], "tip": "Leaving the countryside, or attracted to the city?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["dark", "albedo", "absorb", "concrete", "tarmac"], ["vegetation", "evapotranspiration", "trees"], ["waste heat", "vehicles", "air conditioning", "buildings"]], "tips": ["Surfaces, plants, human heat."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["heat island", "cool", "shade"], ["runoff", "flood", "air quality", "biodiversity", "wellbeing"], ["cost", "space", "maintenance", "land", "conclusion"]], "tips": ["Two benefits and a limitation."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["food", "water", "energy", "materials", "fuel"], ["waste", "sewage", "pollution", "emission", "heat"]], "tips": ["What goes in, what comes out."]}]}, "models": {"1": [["Q1", "Drought and lack of land: push. Jobs and services: pull."]], "2": [["Q2", "Dark surfaces such as tarmac and concrete have low albedo and absorb and store heat [1]; there is less vegetation, so less cooling by evapotranspiration [1]; vehicles, industry and air conditioning release waste heat [1]."]], "3": [["Q3", "Green roofs, parks and street trees cool the city and reduce the urban heat island [1]; they also absorb rainwater runoff, improve air quality, biodiversity and wellbeing [1]; however they need space, money and maintenance, which is hard in dense, low-income areas, so they work best combined with other planning measures [1]."]], "4": [["Q4", "Inputs include food, water, energy and building materials [1]; outputs include solid waste, sewage, air pollution and greenhouse gas emissions [1]."]], "6": [["Exit ticket", "Dark surfaces absorbing heat, lack of vegetation, or waste heat from vehicles and buildings."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '6f8eb8c1-d760-59d7-bb2f-08e37395c3e5', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = '8.3' limit 1), '8.3 Urban air pollution · Lesson 1: Primary and secondary pollutants, smog, temperature inversions and management', 'IB DP ESS · 8.3 Urban air pollution', '/ess83-lesson1/', 'ESS-83-L1', 16, 261 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-83-L1', '8.3 Urban air pollution · Lesson 1: Primary and secondary pollutants, smog, temperature inversions and management', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 5, "n": 5, "ans": ["Primary pollutant", "Secondary pollutant", "Primary pollutant", "Secondary pollutant", "Primary pollutant"], "tip": "Emitted directly or formed by reactions?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["warm air", "warm layer", "above"], ["cool", "cold air", "near the ground", "below"], ["trap", "cannot rise", "not disperse"]], "tips": ["Lid of warm air."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Regulating release", "Altering human activity", "Clean-up", "Regulating release", "Altering human activity"], "tip": "Stop, reduce at the source, or clean afterwards?"}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["nox", "nitrogen oxide", "voc", "vehicle"], ["sunlight", "uv", "light"], ["ozone", "secondary", "react"]], "tips": ["Ingredients + sunlight → product."]}]}, "models": {"1": [["Q1", "CO, soot, NOₓ: primary. Ozone, nitric acid: secondary."]], "2": [["Q2", "In an inversion, a layer of warm air lies above [1] cooler, denser air near the ground [1]; the cool air cannot rise, so pollutants are trapped near the surface and cannot disperse [1]."]], "3": [["Q3", "Catalytic converters and scrubbers: regulating release. Buses and congestion charge: altering activity. Trees: clean-up."]], "4": [["Q4", "Vehicles emit nitrogen oxides and VOCs [1]; in strong sunlight [1] these react to form tropospheric ozone and other secondary pollutants, producing smog [1]."]], "6": [["Exit ticket", "It is not emitted directly but forms from reactions of NOₓ and VOCs in sunlight."]]}, "labels": {"q2_0": "Q2", "q4_0": "Q4", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '6a7f48ce-7d10-510d-b659-f717f94a318a', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = 'HL.a' limit 1), 'HL.a Environmental law · Lesson 1 (HL): International and national environmental law, enforcement and rights of nature', 'IB DP ESS · HL.a Environmental law', '/esshla-lesson1/', 'ESS-HLA-L1', 17, 271 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-HLA-L1', 'HL.a Environmental law · Lesson 1 (HL): International and national environmental law, enforcement and rights of nature', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["International", "National", "Local", "International"], "tip": "Between countries, one country, or one area?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 5, "n": 5, "ans": ["Ramsar", "CITES", "UNCLOS", "Montreal Protocol", "Kunming–Montreal GBF"], "tip": "One each."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["sovereignty", "refuse", "withdraw", "not sign", "ratify"], ["no global", "no police", "voluntary", "sanction"], ["corruption", "funding", "monitor", "economic", "capacity"]], "tips": ["Sovereignty, enforcement body, national capacity."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 3, "pts": [["legal action", "court", "guardian", "protect"], ["indigenous", "intrinsic", "worldview", "value"], ["enforce", "conflict", "develop", "cost", "limitation", "interpret"]], "tips": ["What it allows, values, problems."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["hard+binding", "hard+legally"], ["soft+not binding", "soft+guideline", "soft+declaration", "soft+voluntary"]], "tips": ["Binding or not?"]}]}, "models": {"1": [["Q1", "Paris and CITES: international. Plastic bag ban: national. County by-law: local."]], "2": [["Q2", "Ramsar; CITES; UNCLOS; Montreal; Kunming–Montreal GBF."]], "3": [["Q3", "Countries are sovereign and can refuse to ratify or withdraw from treaties [1]; there is no global authority to police compliance, so enforcement relies on sanctions or peer pressure [1]; some countries lack funding and monitoring capacity, or face corruption and economic pressure [1]."]], "4": [["Q4", "Legal rights allow guardians to take legal action in court to protect the river [1]; they recognise indigenous worldviews and the intrinsic value of nature [1]; however they can be hard to enforce, may conflict with development or water use, and depend on how courts interpret them [1]."]], "5": [["Q5", "Hard law is legally binding, such as a ratified treaty [1]; soft law is not legally binding, such as declarations or guidelines [1]."]], "6": [["Exit ticket", "Taking action to prevent environmental harm even when there is not yet full scientific certainty."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select 'e0a470c6-28d4-51f8-ae91-69483b208d4d', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = 'HL.b' limit 1), 'HL.b Environmental economics · Lesson 1 (HL): Externalities, market failure, valuing nature and economic tools', 'IB DP ESS · HL.b Environmental economics', '/esshlb-lesson1/', 'ESS-HLB-L1', 14, 281 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-HLB-L1', 'HL.b Environmental economics · Lesson 1 (HL): Externalities, market failure, valuing nature and economic tools', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Negative externality", "Positive externality", "Tragedy of the commons", "Tragedy of the commons"], "tip": "Third-party cost, third-party benefit, or shared resource overuse?"}], "2": [{"kind": "text", "id": "q2_0", "q": "Q2", "max": 3, "pts": [["decision", "cost-benefit", "compare", "visible", "policy"], ["intrinsic", "replaceable", "commodif", "difficult", "uncertain"], ["conclusion", "useful", "alongside", "overall"]], "tips": ["Helps decisions vs ethical and practical problems."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["tax+price", "tax+predictable", "tax+revenue"], ["cap+limit", "cap+total", "cap+permit"], ["tax+uncertain", "trade+fluctuat", "trade+price", "both"]], "tips": ["What is fixed in each?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["depletion", "pollution", "environmental", "natural capital"], ["wellbeing", "inequality", "positive", "counts", "ignores"]], "tips": ["What does GDP count and ignore?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q5", "max": 2, "pts": [["pay", "income", "money", "landowner"], ["keep", "protect", "incentive", "value", "forest standing"]], "tips": ["Make standing forest pay."]}]}, "models": {"1": [["Q1", "Cement dust: negative externality. Trees: positive externality. Shared rangeland and ocean fish: tragedy of the commons."]], "2": [["Q2", "Valuing ecosystem services makes their benefits visible in cost–benefit decisions and policy [1]; however valuation is uncertain and may treat nature as replaceable, ignoring intrinsic value [1]; it is useful alongside, not instead of, ethical and legal protection [1]."]], "3": [["Q3", "A carbon tax fixes the price of emitting carbon and raises revenue [1]; cap and trade fixes the total amount of emissions through tradeable permits [1]; under a tax the amount of emission reduction is uncertain, while under cap and trade the permit price fluctuates [1]."]], "4": [["Q4", "GDP ignores the depletion of natural capital and counts pollution and disaster clean-up as positive economic activity [1]; it also ignores inequality and wellbeing [1]."]], "5": [["Q5", "Landowners or communities are paid for the services their forest provides, such as carbon storage or water regulation [1], giving them an income and incentive to keep the forest standing rather than clearing it [1]."]], "6": [["Exit ticket", "A cost or benefit of an activity that falls on third parties and is not included in the price."]]}, "labels": {"q2_0": "Q2", "q3_0": "Q3", "q4_0": "Q4", "q5_0": "Q5", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, sort_order) select '43be7ebe-37f4-56f6-8a13-b8329a8f7f37', (select t.id from public.topics t join public.subjects s on s.id = t.subject_id where s.name = 'IB Environmental Systems & Societies' and t.code = 'HL.c' limit 1), 'HL.c Environmental ethics · Lesson 1 (HL): Ethical frameworks, moral standing and intergenerational justice', 'IB DP ESS · HL.c Environmental ethics', '/esshlc-lesson1/', 'ESS-HLC-L1', 15, 291 on conflict (external_id) do update set title = excluded.title, url = excluded.url, max_marks = excluded.max_marks, topic_id = coalesce(excluded.topic_id, public.lessons.topic_id), sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('ESS-HLC-L1', 'HL.c Environmental ethics · Lesson 1 (HL): Ethical frameworks, moral standing and intergenerational justice', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Utilitarianism", "Deontology", "Virtue ethics", "Utilitarianism"], "tip": "Outcomes, rules or character?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Anthropocentric", "Biocentric", "Ecocentric", "Ecocentric"], "tip": "Humans, individual organisms, or whole systems?"}, {"kind": "text", "id": "q2_1", "q": "Q3", "max": 3, "pts": [["biocentric+individual", "biocentric+each", "biocentric+right to life"], ["ecocentric+ecosystem", "ecocentric+whole", "ecocentric+community"], ["cull", "oppose", "support", "habitat", "other species"]], "tips": ["Individuals vs the whole system."]}], "3": [{"kind": "text", "id": "q3_0", "q": "Q4", "max": 2, "pts": [["future generation", "future"], ["emissions today", "present", "cannot", "consent", "impacts later", "long-lasting"]], "tips": ["Who causes, who suffers."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 2, "pts": [["consequen+outcome", "consequen+result", "consequen+wellbeing"], ["deontolog+duty", "deontolog+rule", "deontolog+regardless"]], "tips": ["Outcomes vs rules."]}]}, "models": {"1": [["Q1", "Dam and suffering: utilitarianism. Always wrong to kill: deontology. Good person: virtue ethics."]], "2": [["Q2", "Water for city: anthropocentric. Each elephant: biocentric. Culling goats and land ethic: ecocentric."], ["Q3", "Biocentric ethics gives moral standing to each individual elephant, so it would oppose killing them [1]; ecocentric ethics values the whole ecosystem and its integrity [1]; so it could support culling if elephants exceed carrying capacity and are destroying habitat for other species [1]."]], "3": [["Q4", "Emissions today will cause impacts that last for centuries and fall mainly on future generations [1], who have no voice in current decisions and cannot consent, so present generations have a duty to limit harm [1]."]], "4": [["Q5", "Utilitarian: if fees protect habitat and many more animals and support local communities, overall wellbeing increases, so it may be justified. Deontology/biocentric: killing a sentient animal for sport is wrong regardless of outcomes. A balanced conclusion might allow it only under strict regulation where evidence shows clear conservation benefits."]], "5": [["Q6", "Consequentialist ethics judges actions by their outcomes, such as maximising overall wellbeing [1]; deontological ethics judges actions by duties or rules, regardless of the consequences [1]."]], "6": [["Exit ticket", "An action is right when it tends to preserve the integrity, stability and beauty of the biotic community."]]}, "labels": {"q2_1": "Q3", "q3_0": "Q4", "q4_0": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
